import re

_HEADER = re.compile(r'^([a-z]+)(\(([^()]+)\))?(!)?: (\S.*)$')

_VERSION = re.compile(r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$')


def _parse_commit(message):
    """Return (type, breaking) for a commit whose header counts, else None."""
    lines = message.split("\n")
    if not lines:
        return None
    header = lines[0]
    m = _HEADER.match(header)
    if not m:
        return None
    ctype = m.group(1)
    breaking = m.group(4) == "!"
    for line in lines[1:]:
        if line.startswith("BREAKING CHANGE: ") or line.startswith("BREAKING-CHANGE: "):
            breaking = True
    return ctype, breaking


def _level(ctype, breaking):
    if breaking:
        return 3
    if ctype == "feat":
        return 2
    if ctype == "fix":
        return 1
    return 0


def next_version(current, commits):
    """The version after `current`, decided by the commit messages. See TASK.md."""
    vm = _VERSION.match(current)
    if not vm:
        raise ValueError("invalid version: {!r}".format(current))
    major, minor, patch = (int(vm.group(i)) for i in (1, 2, 3))

    best = 0
    for message in commits:
        parsed = _parse_commit(message)
        if parsed is None:
            continue
        ctype, breaking = parsed
        best = max(best, _level(ctype, breaking))

    if best == 0:
        return current
    if major >= 1:
        if best == 3:
            return "{}.0.0".format(major + 1)
        if best == 2:
            return "{}.{}.0".format(major, minor + 1)
        return "{}.{}.{}".format(major, minor, patch + 1)
    else:
        if best == 3:
            return "0.{}.0".format(minor + 1)
        return "0.{}.{}".format(minor, patch + 1)
